2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
f2fs: fix out-of-bounds access in sysfs attribute read/write

Some f2fs sysfs attributes suffer from out-of-bounds memory access and
incorrect handling of integer values whose size is not 4 bytes.

For example:
vm:~# echo 65537 > /sys/fs/f2fs/vde/carve_out
vm:~# cat /sys/fs/f2fs/vde/carve_out
65537
vm:~# echo 4294967297 > /sys/fs/f2fs/vde/atgc_age_threshold
vm:~# cat /sys/fs/f2fs/vde/atgc_age_threshold
1

carve_out maps to {struct f2fs_sb_info}->carve_out, which is a 8-bit
integer. However, the sysfs interface allows setting it to a value
larger than 255, resulting in an out-of-range update.

atgc_age_threshold maps to {struct atgc_management}->age_threshold,
which is a 64-bit integer, but its sysfs interface cannot correctly set
values larger than UINT_MAX.

The root causes are:
1. __sbi_store() treats all default values as unsigned int, which
prevents updating integers larger than 4 bytes and causes out-of-bounds
writes for integers smaller than 4 bytes.

2. f2fs_sbi_show() also assumes all default values are unsigned int,
leading to out-of-bounds reads and incorrect access to integers larger
than 4 bytes.

This patch introduces {struct f2fs_attr}->size to record the actual size
of the integer associated with each sysfs attribute. With this
information, sysfs read and write operations can correctly access and
update values according to their real data size, avoiding memory
corruption and truncation.

Fixes: b59d0bae6ca3 ("f2fs: add sysfs support for controlling the gc_thread")
Cc: stable@kernel.org
Signed-off-by: Jinbao Liu <liujinbao1@xiaomi.com>
Signed-off-by: Yongpeng Yang <yangyongpeng@xiaomi.com>
Reviewed-by: Chao Yu <chao@kernel.org>
Signed-off-by: Jaegeuk Kim <jaegeuk@kernel.org>

Here is the root cause:
The sysfs attribute read/write functions (f2fs_sbi_show and __sbi_store) treated all default values as unsigned int (4 bytes), ignoring the actual size of the underlying integer fields. This caused out-of-bounds writes when storing values larger than the field's capacity (e.g., 8-bit field) and incorrect truncation when storing values larger than UINT_MAX into 64-bit fields. The patch introduces a size field to handle proper type-specific access.

Here is the patch:
 	int struct_type;
 	int offset;
+	int size;
 	int id;
 };

+static ssize_t __sbi_show_value(struct f2fs_attr *a,
+		struct f2fs_sb_info *sbi, char *buf,
+		unsigned char *value)
+{
+	switch (a->size) {
+	case 1:
+		return sysfs_emit(buf, "%u\n", *(u8 *)value);
+	case 2:
+		return sysfs_emit(buf, "%u\n", *(u16 *)value);
+	case 4:
+		return sysfs_emit(buf, "%u\n", *(u32 *)value);
+	case 8:
+		return sysfs_emit(buf, "%llu\n", *(u64 *)value);
+	default:
+		f2fs_bug_on(sbi, 1);
+		return sysfs_emit(buf,
+				"show sysfs node value with wrong type\n");
+	}
+}
+
 static ssize_t f2fs_sbi_show(struct f2fs_attr *a,
 			struct f2fs_sb_info *sbi, char *buf)
 {
 	unsigned char *ptr = NULL;
-	unsigned int *ui;

 	ptr = __struct_ptr(sbi, a->struct_type);
 	if (!ptr)
 		return -EINVAL;

 	if (!strcmp(a->attr.name, "extension_list")) {
 		__u8 (*extlist)[F2FS_EXTENSION_LEN] =
 					sbi->raw_super->extension_list;
 		int cold_count = le32_to_cpu(sbi->raw_super->extension_count);
 		int hot_count = sbi->raw_super->hot_ext_count;
 		int len = 0, i;

 		len += sysfs_emit_at(buf, len, "cold file extension:\n");
 		for (i = 0; i < cold_count; i++)
 			len += sysfs_emit_at(buf, len, "%s\n", extlist[i]);

 		len += sysfs_emit_at(buf, len, "hot file extension:\n");
 		for (i = cold_count; i < cold_count + hot_count; i++)
 			len += sysfs_emit_at(buf, len, "%s\n", extlist[i]);

 		return len;
 	}

 	if (!strcmp(a->attr.name, "ckpt_thread_ioprio")) {
 		struct ckpt_req_control *cprc = &sbi->cprc_info;
 		int class = IOPRIO_PRIO_CLASS(cprc->ckpt_thread_ioprio);
 		int level = IOPRIO_PRIO_LEVEL(cprc->ckpt_thread_ioprio);

 		if (class != IOPRIO_CLASS_RT && class != IOPRIO_CLASS_BE)
 			return -EINVAL;

 		return sysfs_emit(buf, "%s,%d\n",
 			class == IOPRIO_CLASS_RT ? "rt" : "be", level);
 	}

 #ifdef CONFIG_F2FS_FS_COMPRESSION
 	if (!strcmp(a->attr.name, "compr_written_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->compr_written_block);

 	if (!strcmp(a->attr.name, "compr_saved_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->compr_saved_block);

 	if (!strcmp(a->attr.name, "compr_new_inode"))
 		return sysfs_emit(buf, "%u\n", sbi->compr_new_inode);
 #endif

 	if (!strcmp(a->attr.name, "gc_segment_mode"))
 		return sysfs_emit(buf, "%u\n", sbi->gc_segment_mode);

 	if (!strcmp(a->attr.name, "gc_reclaimed_segments")) {
 		return sysfs_emit(buf, "%u\n",
 			sbi->gc_reclaimed_segs[sbi->gc_segment_mode]);
 	}

 	if (!strcmp(a->attr.name, "current_atomic_write")) {
 		s64 current_write = atomic64_read(&sbi->current_atomic_write);

 		return sysfs_emit(buf, "%lld\n", current_write);
 	}

 	if (!strcmp(a->attr.name, "peak_atomic_write"))
 		return sysfs_emit(buf, "%lld\n", sbi->peak_atomic_write);

 	if (!strcmp(a->attr.name, "committed_atomic_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->committed_atomic_block);

 	if (!strcmp(a->attr.name, "revoked_atomic_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->revoked_atomic_block);

 #ifdef CONFIG_F2FS_STAT_FS
 	if (!strcmp(a->attr.name, "cp_foreground_calls"))
 		return sysfs_emit(buf, "%d\n",
 				atomic_read(&sbi->cp_call_count[TOTAL_CALL]) -
 				atomic_read(&sbi->cp_call_count[BACKGROUND]));
 	if (!strcmp(a->attr.name, "cp_background_calls"))
 		return sysfs_emit(buf, "%d\n",
 				atomic_read(&sbi->cp_call_count[BACKGROUND]));
 #endif

-	ui = (unsigned int *)(ptr + a->offset);
+	return __sbi_show_value(a, sbi, buf, ptr + a->offset);
+}

-	return sysfs_emit(buf, "%u\n", *ui);
+static void __sbi_store_value(struct f2fs_attr *a,
+			struct f2fs_sb_info *sbi,
+			unsigned char *ui, unsigned long value)
+{
+	switch (a->size) {
+	case 1:
+		*(u8 *)ui = value;
+		break;
+	case 2:
+		*(u16 *)ui = value;
+		break;
+	case 4:
+		*(u32 *)ui = value;
+		break;
+	case 8:
+		*(u64 *)ui = value;
+		break;
+	default:
+		f2fs_bug_on(sbi, 1);
+		f2fs_err(sbi, "store sysfs node value with wrong type");
+	}
 }

 static ssize_t __sbi_store(struct f2fs_attr *a,
 			struct f2fs_sb_info *sbi,
 			const char *buf, size_t count)
 {
 	unsigned char *ptr;
 	unsigned long t;
 	unsigned int *ui;
 	ssize_t ret;

 	ptr = __struct_ptr(sbi, a->struct_type);
 	if (!ptr)
 		return -EINVAL;

 	if (!strcmp(a->attr.name, "extension_list")) {
 		const char *name = strim((char *)buf);
 		bool set = true, hot;

 		if (!strncmp(name, "[h]", 3))
 			hot = true;
 		else if (!strncmp(name, "[c]", 3))
 			hot = false;
 		else
 			return -EINVAL;

 		name += 3;

 		if (*name == '!') {
 			name++;
 			set = false;
 		}

 		if (!strlen(name) || strlen(name) >= F2FS_EXTENSION_LEN)
 			return -EINVAL;

 		f2fs_down_write(&sbi->sb_lock);

 		ret = f2fs_update_extension_list(sbi, name, hot, set);
 		if (ret)
 			goto out;

 		ret = f2fs_commit_super(sbi, false);
 		if (ret)
 			f2fs_update_extension_list(sbi, name, hot, !set);
 out:
 		f2fs_up_write(&sbi->sb_lock);
 		return ret ? ret : count;
 	}

 	if (!strcmp(a->attr.name, "ckpt_thread_ioprio")) {
 		const char *name = strim((char *)buf);
 		struct ckpt_req_control *cprc = &sbi->cprc_info;
 		int class;
 		long level;
 		int ret;

 		if (!strncmp(name, "rt,", 3))
 			class = IOPRIO_CLASS_RT;
 		else if (!strncmp(name, "be,", 3))
 			class = IOPRIO_CLASS_BE;
 		else
 			return -EINVAL;

 		name += 3;
 		ret = kstrtol(name, 10, &level);
 		if (ret)
 			return ret;
 		if (level >= IOPRIO_NR_LEVELS || level < 0)
 			return -EINVAL;

 		cprc->ckpt_thread_ioprio = IOPRIO_PRIO_VALUE(class, level);
 		if (test_opt(sbi, MERGE_CHECKPOINT)) {
 			ret = set_task_ioprio(cprc->f2fs_issue_ckpt,
 					cprc->ckpt_thread_ioprio);
 			if (ret)
 				return ret;
 		}

 		return count;
 	}

 	ui = (unsigned int *)(ptr + a->offset);

 	ret = kstrtoul(skip_spaces(buf), 0, &t);
 	if (ret < 0)
 		return ret;
 #ifdef CONFIG_F2FS_FAULT_INJECTION
 	if (a->struct_type == FAULT_INFO_TYPE) {
 		if (f2fs_build_fault_attr(sbi, 0, t, FAULT_TYPE))
 			return -EINVAL;
 		return count;
 	}
 	if (a->struct_type == FAULT_INFO_RATE) {
 		if (f2fs_build_fault_attr(sbi, t, 0, FAULT_RATE))
 			return -EINVAL;
 		return count;
 	}
 	if (a->struct_type == FAULT_INFO_TIMEOUT) {
 		if (f2fs_build_fault_attr(sbi, 0, t, FAULT_TIMEOUT))
 			return -EINVAL;
 		f2fs_simulate_lock_timeout(sbi);
 		return count;
 	}
 #endif
 	if (a->struct_type == RESERVED_BLOCKS) {
 		spin_lock(&sbi->stat_lock);
 		if (t > (unsigned long)(sbi->user_block_count -
 				F2FS_OPTION(sbi).root_reserved_blocks)) {
 			spin_unlock(&sbi->stat_lock);
 			return -EINVAL;
 		}
 		*ui = t;
 		sbi->current_reserved_blocks = min(sbi->reserved_blocks,
 				sbi->user_block_count - valid_user_blocks(sbi));
 		spin_unlock(&sbi->stat_lock);
 		return count;
 	}

 	if (!strcmp(a->attr.name, "discard_io_aware_gran")) {
 		if (t > MAX_PLIST_NUM)
 			return -EINVAL;
 		if (!f2fs_block_unit_discard(sbi))
 			return -EINVAL;
 		if (t == *ui)
 			return count;
 		*ui = t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "discard_granularity")) {
 		if (t == 0 || t > MAX_PLIST_NUM)
 			return -EINVAL;
 		if (!f2fs_block_unit_discard(sbi))
 			return -EINVAL;
 		if (t == *ui)
 			return count;
 		*ui = t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "max_ordered_discard")) {
 		if (t == 0 || t > MAX_PLIST_NUM)
 			return -EINVAL;
 		if (!f2fs_block_unit_discard(sbi))
 			return -EINVAL;
 		*ui = t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "discard_urgent_util")) {
 		if (t > 100)
 			return -EINVAL;
 		*ui = t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "discard_io_aware")) {
 		if (t >= DPOLICY_IO_AWARE_MAX)
 			return -EINVAL;
 		*ui = t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "migration_granularity")) {
 		if (t == 0 || t > SEGS_PER_SEC(sbi))
 			return -EINVAL;
 	}

 	if (!strcmp(a->attr.name, "migration_window_granularity")) {
 		if (t == 0 || t > SEGS_PER_SEC(sbi))
 			return -EINVAL;
 	}

 	if (!strcmp(a->attr.name, "gc_urgent")) {
 		if (t == 0) {
 			sbi->gc_mode = GC_NORMAL;
 		} else if (t == 1) {
 			sbi->gc_mode = GC_URGENT_HIGH;
 			if (sbi->gc_thread) {
 				sbi->gc_thread->gc_wake = true;
 				wake_up_interruptible_all(
 					&sbi->gc_thread->gc_wait_queue_head);
 				wake_up_discard_thread(sbi, true);
 			}
 		} else if (t == 2) {
 			sbi->gc_mode = GC_URGENT_LOW;
 		} else if (t == 3) {
 			sbi->gc_mode = GC_URGENT_MID;
 			if (sbi->gc_thread) {
 				sbi->gc_thread->gc_wake = true;
 				wake_up_interruptible_all(
 					&sbi->gc_thread->gc_wait_queue_head);
 			}
 		} else {
 			return -EINVAL;
 		}
 		return count;
 	}
 	if (!strcmp(a->attr.name, "gc_idle")) {
 		if (t == GC_IDLE_CB) {
 			sbi->gc_mode = GC_IDLE_CB;
 		} else if (t == GC_IDLE_GREEDY) {
 			sbi->gc_mode = GC_IDLE_GREEDY;
 		} else if (t == GC_IDLE_AT) {
 			if (!sbi->am.atgc_enabled)
 				return -EINVAL;
 			sbi->gc_mode = GC_IDLE_AT;
 		} else {
 			sbi->gc_mode = GC_NORMAL;
 		}
 		return count;
 	}

 	if (!strcmp(a->attr.name, "gc_remaining_trials")) {
 		spin_lock(&sbi->gc_remaining_trials_lock);
 		sbi->gc_remaining_trials = t;
 		spin_unlock(&sbi->gc_remaining_trials_lock);

 		return count;
 	}

 	if (!strcmp(a->attr.name, "gc_no_zoned_gc_percent")) {
 		if (t > 100)
 			return -EINVAL;
 		*ui = (unsigned int)t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "gc_boost_zoned_gc_percent")) {
 		if (t > 100)
 			return -EINVAL;
 		*ui = (unsigned int)t;
 		return count;
 	}

 	if (!strcmp(a->attr.name, "gc_valid_thresh_ratio")) {
 		if (t > 100)
 			return -EINVAL;
 		*ui = (unsigned int)t;
 		return count;
 	}

 #ifdef CONFIG_F2FS_IOSTAT
 	if (!strcmp(a->attr.name, "iostat_enable")) {
 		sbi->iostat_enable = !!t;
 		if (!sbi->iostat_enable)
 			f2fs_reset_iostat(sbi);
 		return count;
 	}

 	if (!strcmp(a->attr.name, "iostat_period_ms")) {
 		if (t < MIN_IOSTAT_PERIOD_MS || t > MAX_IOSTAT_PERIOD_MS)
 			return -EINVAL;
 		spin_lock_irq(&sbi->iostat_lock);
 		sbi->iostat_period_ms = (unsigned int)t;
 		spin_unlock_irq(&sbi->iostat_lock);
 		return count;
 	}
 #endif

 #ifdef CONFIG_BLK_DEV_ZONED
 	if (!strcmp(a->attr.name, "blkzone_alloc_policy")) {
 		if (t < BLKZONE_ALLOC_PRIOR_SEQ || t > BLKZONE_ALLOC_PRIOR_CONV)
 			return -EINVAL;
 		sbi->blkzone_alloc_policy = t;
 		return count;
 	}
 #endif

 #ifdef CONFIG_F2FS_FS_COMPRESSION
 	if (!strcmp(a->attr.name, "compr_written_block") ||
 		!strcmp(a->attr.name, "compr_saved_block")) {
